import { pxToRem } from "../../helpers";
import { StyleFn } from "..";

export const Toast: StyleFn = (theme, mode) => {
  const { color, elevation, font, responsive, size } = theme;

  return {
    root: {
      zIndex: elevation.zindex.banner,
      display: "flex",
      flexDirection: "column",
      justifyContent: "center",
      width: pxToRem(328),
      minHeight: size.spacing[40],
      fontSize: font.size.small,
      fontWeight: font.weight.regular,
      lineHeight: font.lineheight.small,
      color: color.text.neutral.default[mode],
      backgroundColor: color.surface.elevation[6][mode],
      padding: `${size.spacing[8]} ${size.spacing[16]}`,
      paddingLeft: `calc(${size.spacing[16]} + ${size.spacing[8]})`,
      borderRadius: size.radius[3],
      boxShadow: elevation.level6,
      gap: size.spacing[8],
      overflow: "hidden",
      position: "relative",
      "&:before": {
        position: "absolute",
        content: "''",
        top: 0,
        left: 0,
        bottom: 0,
        width: size.spacing[8],
        backgroundColor: color.surface.feedback.information.default[mode],
      },
      [`@media (max-width: ${responsive.breakpoint.xs}px)`]: { width: "100%" },
    },
    header: {
      display: "flex",
      alignItems: "flex-start",
      minHeight: size.spacing[24],
    },
    heading: {
      flex: "1 1 0%",
      fontSize: font.size.medium,
      fontWeight: font.weight.bold,
      wordBreak: "break-word",
      lineHeight: font.lineheight.medium,
    },
    time: {
      flex: "0 0 auto",
      marginLeft: "auto",
      paddingLeft: size.spacing[8],
      fontSize: font.size.xsmall,
      lineHeight: font.lineheight.medium,
      color: color.text.neutral.strong[mode],
      whiteSpace: "nowrap",
    },
    removeBtn: {
      // increase specificity
      "&$removeBtn": { position: "absolute" },
      top: "50%",
      right: size.spacing[8],
      transform: "translate(0, -50%)",
    },
    _inline: {
      minHeight: size.spacing[56],
      width: pxToRem(600),
      [`@media (max-width: ${responsive.breakpoint.sm}px)`]: { width: "100%" },
    },
    _withRemove: {
      paddingRight: size.spacing[64],
      "& $time": {
        right: size.spacing[80],
      },
      "&:after": {
        position: "absolute",
        content: "''",
        top: size.spacing[8],
        right: size.spacing[48],
        bottom: size.spacing[8],
        width: 1,
        backgroundColor: color.border.neutral.default[mode],
      },
    },
    _info: {},
    _success: {
      "&:before": {
        backgroundColor: color.surface.feedback.success.default[mode],
      },
    },
    _warning: {
      "&:before": {
        backgroundColor: color.surface.feedback.warning.default[mode],
      },
    },
    _error: {
      "&:before": {
        backgroundColor: color.surface.feedback.error.default[mode],
      },
    },
  };
};
